/* Rotate the actual globe and its pins with grip, tracked pinch or mouse drag. */
(()=>{
AFRAME.registerComponent('globe-rotation',{
 init(){const T=AFRAME.THREE;this.T=T;this.bindings=[];this.center=new T.Vector3();this.ray=new T.Ray();this.sphere=new T.Sphere();this.v=new T.Vector3();this.q=new T.Quaternion();this.clean=()=>this.release();this.listen(window,'blur',this.clean);this.listen(document,'visibilitychange',this.clean);this.listen(this.el.sceneEl,'exit-vr',this.clean);for(const id of ['leftHand','rightHand']){const hand=document.getElementById(id);this.listen(hand,'gripdown',()=>this.grip(hand));this.listen(hand,'gripup',()=>{if(this.source===hand)this.release()});this.listen(hand,'controllerdisconnected',this.clean)}const rig=document.getElementById('rig');for(const side of ['left','right']){const hand=document.createElement('a-entity');hand.id=side==='left'?'globiquestLeftTrackedHand':'globiquestRightTrackedHand';hand.setAttribute('spatial-hand-ui','');hand.setAttribute('hand-tracking-controls',`hand:${side}; modelStyle:mesh`);rig.append(hand);this.listen(hand,'pinchstarted',e=>this.pinchStart(hand,e.detail.position));this.listen(hand,'pinchmoved',e=>this.pinchMove(hand,e.detail.position));this.listen(hand,'pinchended',()=>{if(this.source===hand)this.release()});this.tracked ||= [];this.tracked.push(hand)}this.listen(this.el.sceneEl,'renderstart',()=>this.desktop());if(this.el.sceneEl.canvas)this.desktop();},
 listen(el,name,fn,options){if(!el)return;el.addEventListener(name,fn,options);this.bindings.push(()=>el.removeEventListener(name,fn,options))},
 target(origin,direction){if(window.globiquest.workspace==='music')return false;const globe=document.getElementById('mapRoot');if(!globe.object3D.visible||window.globiquest?.parachutes&&document.querySelector('[parachute-arcade]')?.components['parachute-arcade']?.open)return false;globe.object3D.getWorldPosition(this.center);const scale=globe.object3D.getWorldScale(this.v).x;this.sphere.set(this.center,1.24*scale);this.ray.set(origin,direction);return !!this.ray.intersectSphere(this.sphere,new this.T.Vector3())},
 begin(source,kind){if(this.source)return false;this.source=source;this.kind=kind;this.initial=this.el.object3D.quaternion.clone();this.el.object3D.getWorldQuaternion(this.initialWorld=new this.T.Quaternion());this.el.object3D.parent.getWorldQuaternion(this.parentInverse=new this.T.Quaternion()).invert();return true},
 movable(origin,direction){if(window.globiquest.parachutes?.open)return null;const scope=document.getElementById('celestialTelescope');if(this.armed&&scope)return {el:scope,distance:Math.max(.5,origin.distanceTo(scope.object3D.getWorldPosition(new this.T.Vector3())))};const hits=[];for(const [id,y,radius] of [['celestialTelescope',.48,.65],['celestialTelescope',1.3,.72],['lens',0,.44]]){const el=document.getElementById(id);if(!el||id==='celestialTelescope'&&y>1&&!window.globiquest?.scopeActive)continue;let visible=true;for(let p=el.object3D;p;p=p.parent)if(!p.visible)visible=false;if(!visible)continue;const center=el.object3D.localToWorld(new this.T.Vector3(0,y,0)),scale=el.object3D.getWorldScale(new this.T.Vector3()).x;const hit=new this.T.Ray(origin,direction).intersectSphere(new this.T.Sphere(center,radius*scale),new this.T.Vector3());if(hit)hits.push({el,distance:Math.max(.4,origin.distanceTo(hit))})}return hits.sort((a,b)=>a.distance-b.distance)[0]||null},
 controllerRay(hand){const ray=hand.components?.raycaster?.raycaster?.ray;return ray?ray.clone():new this.T.Ray(hand.object3D.getWorldPosition(new this.T.Vector3()),new this.T.Vector3(0,0,-1).applyQuaternion(hand.object3D.getWorldQuaternion(new this.T.Quaternion())))},
 grip(hand){if(window.globiquest?.lensHeld||window.globiquest?.travelEditing||window.globiquest.handInputReserved?.(hand))return;const origin=new this.T.Vector3(),direction=new this.T.Vector3();const ray=this.controllerRay(hand);origin.copy(ray.origin);direction.copy(ray.direction);hand.object3D.getWorldQuaternion(this.q);const movable=this.movable(origin,direction);if(!movable&&window.globiquest.globePatch?.enabled)return;if(movable){if(!this.begin(hand,'controller'))return;this.armed=false;this.moving=movable.el;if(typeof notify==='function')notify('Telescope held · move your controller, then release grip to place.');this.moveDistance=movable.distance;this.moveStart=this.moving.object3D.getWorldPosition(new this.T.Vector3());this.aimStart=origin.clone().addScaledVector(direction,this.moveDistance);this.moving.object3D.getWorldQuaternion(this.initialWorld);this.moving.object3D.parent.getWorldQuaternion(this.parentInverse).invert()}else{if(!this.target(origin,direction)||!this.begin(hand,'controller'))return}this.startGrip=this.q.clone().invert();},
 handPoint(hand,p){return hand.object3D.parent.localToWorld(new this.T.Vector3(p.x,p.y,p.z))},
 pinchStart(hand,p,objectOnly=false){if(window.globiquest?.travelEditing||!objectOnly&&(window.globiquest.handUIIsTarget?.(hand,p)||window.globiquest.handInputReserved?.(hand,p)))return;const point=this.handPoint(hand,p),camera=this.el.sceneEl.camera,origin=new this.T.Vector3();camera.getWorldPosition(origin);const direction=point.clone().sub(origin).normalize(),native=window.globiquest.handRay?.(hand,p);if(native){origin.copy(native.origin);direction.copy(native.direction)}const movable=this.movable(origin,direction);if(!movable&&window.globiquest.globePatch?.enabled)return;if(!movable&&!this.target(origin,direction))return;if(!this.begin(hand,'pinch'))return;if(movable){this.armed=false;this.moving=movable.el;if(typeof notify==='function')notify((this.moving.id==='lens'?'Magnifier':'Telescope')+' selected · move to reposition, release to place.');this.moveStart=this.moving.object3D.getWorldPosition(new this.T.Vector3());this.moveGain=Math.min(this.moving.id==='celestialTelescope'?1.35:4,Math.max(1,movable.distance/Math.max(.2,point.distanceTo(origin))))}this.startPoint=point;this.cameraInverse=camera.getWorldQuaternion(new this.T.Quaternion()).invert();this.lastPinch=performance.now()},
 pinchMove(hand,p){if(this.source!==hand||this.kind!=='pinch')return;const delta=this.handPoint(hand,p).sub(this.startPoint);if(this.moving){const world=this.moveStart.clone().addScaledVector(delta,this.moveGain);this.place(world)}else{delta.applyQuaternion(this.cameraInverse);this.drag(delta.x*3.5,-delta.y*3.5)}this.lastPinch=performance.now()},
 drag(yaw,pitch){const turn=new this.T.Quaternion().setFromEuler(new this.T.Euler(pitch,yaw,0,'YXZ'));this.el.object3D.quaternion.copy(turn.multiply(this.initial)).normalize()},
 desktop(){if(this.desktopReady)return;const canvas=this.el.sceneEl.canvas;if(!canvas)return;this.desktopReady=true;this.listen(canvas,'pointerdown',e=>{if(e.button!==0||e.shiftKey||this.el.sceneEl.is('vr-mode'))return;const rect=canvas.getBoundingClientRect(),mouse=new this.T.Vector2((e.clientX-rect.left)/rect.width*2-1,-(e.clientY-rect.top)/rect.height*2+1),caster=new this.T.Raycaster();caster.setFromCamera(mouse,this.el.sceneEl.camera);const movable=this.movable(caster.ray.origin,caster.ray.direction);if(!movable&&window.globiquest.globePatch?.enabled)return;if(!movable&&!this.target(caster.ray.origin,caster.ray.direction))return;if(!this.begin(canvas,'mouse'))return;if(movable){this.armed=false;this.moving=movable.el;if(typeof notify==='function')notify((this.moving.id==='lens'?'Magnifier':'Telescope')+' selected · move to reposition, release to place.');this.moveStart=this.moving.object3D.getWorldPosition(new this.T.Vector3());this.mousePlane=new this.T.Plane().setFromNormalAndCoplanarPoint(this.el.sceneEl.camera.getWorldDirection(new this.T.Vector3()),this.moveStart);this.mouseStart=caster.ray.intersectPlane(this.mousePlane,new this.T.Vector3())}this.pointer={x:e.clientX,y:e.clientY,id:e.pointerId};this.look=document.getElementById('camera');this.lookWasEnabled=this.look.getAttribute('look-controls')?.enabled!==false;this.look.setAttribute('look-controls','enabled',false)},true);this.listen(window,'pointermove',e=>{if(this.kind!=='mouse'||e.pointerId!==this.pointer.id)return;const dx=e.clientX-this.pointer.x,dy=e.clientY-this.pointer.y;if(this.moving&&this.mouseStart){const rect=canvas.getBoundingClientRect(),caster=new this.T.Raycaster();caster.setFromCamera(new this.T.Vector2((e.clientX-rect.left)/rect.width*2-1,-(e.clientY-rect.top)/rect.height*2+1),this.el.sceneEl.camera);const hit=caster.ray.intersectPlane(this.mousePlane,new this.T.Vector3());if(hit)this.place(hit.sub(this.mouseStart).add(this.moveStart))}else this.drag(dx*.006,dy*.006);if(Math.abs(dx)+Math.abs(dy)>6)this.suppressUntil=performance.now()+300});this.listen(window,'pointerup',()=>{if(this.kind==='mouse')this.release()});this.listen(window,'pointercancel',this.clean);for(const id of ['mapRoot','celestialTelescope','lens'])this.listen(document.getElementById(id),'click',e=>{if(performance.now()<(this.suppressUntil||0)){e.stopPropagation();e.stopImmediatePropagation()}},true)},
 place(world){if(['lens','celestialTelescope'].includes(this.moving.id)){this.moving.dataset ||= {};this.moving.dataset.userPlaced='true';for(const [key,r] of window.globiquest.objectSizer?.positions||[])if(r.object===this.moving.object3D)window.globiquest.objectSizer.positions.delete(key)}world.y=Math.max(.35,Math.min(3.5,world.y));this.moving.object3D.position.copy(this.moving.object3D.parent.worldToLocal(world));if(this.moving.id==='celestialTelescope'){const T=this.T,object=this.moving.object3D,head=window.globiquest.xrHeadPose?.()?.position||this.el.sceneEl.camera.getWorldPosition(new T.Vector3()),center=document.getElementById('scopeView')?.object3D.getWorldPosition(new T.Vector3())||object.getWorldPosition(new T.Vector3()),direction=head.clone().sub(center);direction.y=0;if(direction.lengthSq()>.0001)object.quaternion.copy(object.parent.getWorldQuaternion(new T.Quaternion()).invert()).multiply(new T.Quaternion().setFromUnitVectors(new T.Vector3(0,0,1),direction.normalize()));object.updateWorldMatrix(true,true)}},
 release(){if(this.kind==='mouse'&&this.look)this.look.setAttribute('look-controls','enabled',this.lookWasEnabled);this.source=null;this.kind=null;this.moving=null},
 tick(){if(this.kind==='pinch'&&performance.now()-this.lastPinch>400)this.release();if(this.kind!=='controller')return;const current=this.source.object3D.getWorldQuaternion(new this.T.Quaternion());current.multiply(this.startGrip).multiply(this.initialWorld);const object=this.moving?.object3D||this.el.object3D;object.quaternion.copy(this.parentInverse).multiply(current).normalize();if(this.moving){const ray=this.controllerRay(this.source);const world=ray.origin.addScaledVector(ray.direction,this.moveDistance).sub(this.aimStart).add(this.moveStart);this.place(world)}},
 remove(){this.release();this.bindings.forEach(fn=>fn());this.tracked?.forEach(hand=>hand.remove())}
});
const setup=()=>{document.getElementById('earthRoot').setAttribute('globe-rotation','');const move=document.createElement('button');move.type='button';move.hidden=true;move.innerHTML='<span>↔</span>Move scope';move.setAttribute('aria-label','Select telescope for repositioning');move.onclick=()=>{const component=document.getElementById('earthRoot').components['globe-rotation'];if(component){component.armed=true;notify('Move telescope: drag anywhere in the scene, or hold controller grip / pinch and move.')}};document.getElementById('spatialDock').append(move);const rotate=document.createElement('button');rotate.type='button';rotate.textContent='↻ Rotate globe';rotate.onclick=()=>{window.globiquest.rotateGlobeMode?.();window.globiquest.renderXRNav?.(document.getElementById('nav'))};document.getElementById('spatialDock').append(rotate);const help=document.getElementById('help');help.innerHTML+=' <br>Globe: drag · Quest: aim + hold grip · Hands: aim a pinch, then move. Telescope: pinch or grip to reposition; release to place.';};if(scene.hasLoaded)setup();else scene.addEventListener('loaded',setup,{once:true});
})();
